{
  "technical_and_design_decisions": [
    "Use Spring Framework 6.0+ requiring Java 17+.",
    "Package custom modules as uber-jars for deployment.",
    "Utilize Spring's native WebSocket support for the full-duplex communication sink.",
    "Use Bamboo as the primary CI tool for both EC2 (Linux) and Windows environments.",
    "Manage shared dependencies via an 'xd/lib' directory, with an uber-jar bundling fallback to resolve classloader conflicts."
  ],
  "assumptions": [
    "Access to HDFS is already provisioned and configured.",
    "The Bamboo CI server is already running and accessible for both Linux and Windows agents.",
    "Required services like Redis and RabbitMQ can be installed and run on the Windows CI environment.",
    "The development team has sufficient knowledge of Spring Framework, Java 17, and the existing CI infrastructure.",
    "The custom module architecture is already defined, and only documentation, sink implementation, and hosting are needed."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Custom Module Documentation",
      "activity_description": "Create documentation detailing recommended standards and patterns for building custom modules based on the Spring Framework.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "HDFS Hosting for Custom Modules",
      "activity_description": "Implement the mechanism to host the custom module (built as an uber-jar) in HDFS so it can be deployed to newly arriving containers.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Native WebSocket Sink Implementation",
      "activity_description": "Develop and integrate a native WebSocket sink to enable full-duplex communication channels over a single TCP connection.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "CI Options Research & npm-cache Integration",
      "activity_description": "Research CI options to improve build stability and reliability, specifically evaluating and integrating npm-cache to cache previously installed dependencies.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5",
      "activity_name": "EC2 CI Infrastructure Improvements",
      "activity_description": "Update the EC2 CI infrastructure by enabling distributed JVM tests, switching from the Artifactory Gradle task to a command task (./gradlew), testing with embedded Hadoop off, and turning on maxParallelForks.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6",
      "activity_name": "PMD/Sonar Violations Investigation & Fix",
      "activity_description": "Investigate the increase in WARN logs, troubleshoot and fix PMD/Sonar violations, and configure Sonar to notify the committer of violations.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A7",
      "activity_name": "Windows OS CI Infrastructure Setup",
      "activity_description": "Set up CI infrastructure on Windows OS using the existing Bamboo environment, gain access to PowerShell, set up required services (Redis, RabbitMQ, etc.), and kick off the CI task for commit-triggered builds.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "Shared Library Location & Classloader Strategy",
      "activity_description": "Configure a common shared location (xd/lib folder) for dependent JARs required by multiple custom modules and document the classloader workaround for different JAR versions.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 40
  }
}
